## 四、2.4 线性表的顺序表示和实现 ★★★

### 4.1 顺序存储：位置就是关系（2.4.1）

把表放进**一片连续内存**，第 i 个元素就住在固定偏移处：

```text
内存:  [a₁][a₂][a₃][a₄][a₅]……[aₙ]  （每个格子一样大 = d 字节）
下标:    0   1   2   3   4        n-1
位序:    1   2   3   4   5        n

LOC(aᵢ) = LOC(a₁) + (i-1) × d     ← 教材式(2.1)
```

这条公式是顺序表一切优点的来源：**知道 i 就能直接算出地址，不用找** —— 这叫**随机存取**，取第 i 个元素 O(1)。链表做不到这点，这是两者一切差异的根源。

C 语言实现（动态分配版，教材 SqList 的标准翻译）：

```c
typedef struct {
    ElemType *elem;   /* 存储空间基址 */
    int length;       /* 当前元素个数 */
    int listsize;     /* 当前已分配容量 */
} SqList;
```

```cpp
// C++ 版：vector 顶掉 elem/length/listsize 三件套
#include <vector>
using namespace std;

struct SqListCpp {
    vector<int> a;        // a.size() 就是 length，容量 vector 自己管
};
```

### 4.2 基本操作实现（2.4.2）★★★

完整实现 + 演示（gcc 实跑）：

```c
#include <stdio.h>
#include <stdlib.h>

#define OK 1
#define ERROR 0
typedef int Status;
typedef int ElemType;

/* ---- 顺序表（动态分配版，教材 2.4）----
   教材的 SqList &L 在标准 C 里翻成 SqList *L */
typedef struct {
    ElemType *elem;   /* 存储空间基址 */
    int length;       /* 当前元素个数 */
    int listsize;     /* 当前已分配容量 */
} SqList;

Status InitList(SqList *L, int cap) {
    L->elem = (ElemType *)malloc(cap * sizeof(ElemType));
    if (!L->elem) return ERROR;
    L->length = 0;
    L->listsize = cap;
    return OK;
}

/* 插入：位序 i 从 1 起，合法范围 1 <= i <= length+1 */
Status ListInsert(SqList *L, int i, ElemType e) {
    if (i < 1 || i > L->length + 1) return ERROR;   /* 位序越界 */
    if (L->length >= L->listsize)   return ERROR;   /* 演示版不扩容 */
    for (int j = L->length - 1; j >= i - 1; j--)    /* 从后往前整体后移 */
        L->elem[j + 1] = L->elem[j];
    L->elem[i - 1] = e;
    L->length++;
    return OK;
}

/* 删除：位序 i，合法范围 1 <= i <= length；用 *e 带回被删值 */
Status ListDelete(SqList *L, int i, ElemType *e) {
    if (i < 1 || i > L->length) return ERROR;
    *e = L->elem[i - 1];
    for (int j = i; j < L->length; j++)             /* 从前往后整体前移 */
        L->elem[j - 1] = L->elem[j];
    L->length--;
    return OK;
}

/* 按值查找：返回位序（1 起），0 表示不存在 */
int LocateElem(SqList *L, ElemType e) {
    for (int i = 0; i < L->length; i++)
        if (L->elem[i] == e) return i + 1;
    return 0;
}

void PrintList(const char *name, SqList *L) {
    printf("%-14s: [", name);
    for (int i = 0; i < L->length; i++)
        printf("%d%s", L->elem[i], i + 1 < L->length ? ", " : "");
    printf("]  length=%d\n", L->length);
}

int main(void) {
    SqList L;
    InitList(&L, 20);
    for (int i = 1; i <= 5; i++) ListInsert(&L, i, i * 10);   /* 尾插 */
    PrintList("尾插10~50", &L);

    ListInsert(&L, 3, 99);                                    /* 中间插 */
    PrintList("位序3插99", &L);

    ElemType e;
    ListDelete(&L, 1, &e);                                    /* 头删 */
    printf("删除位序1，带出 %d\n", e);
    PrintList("删除后", &L);

    printf("查找 40 -> 位序 %d；查找 7 -> 位序 %d（0=不存在）\n",
           LocateElem(&L, 40), LocateElem(&L, 7));

    printf("在位序 9 插入（越界，合法最大 6）-> %d\n", ListInsert(&L, 9, 1));
    printf("删除位序 9（越界，合法最大 5）-> %d\n", ListDelete(&L, 9, &e));
    free(L.elem);
    return 0;
}
```

```cpp
// C++ 版：三个核心操作搬进类里，搬移语义不变（vector 内部同样是整体后移 O(n)）
struct SqListCpp {
    vector<int> a;
    bool ListInsert(int i, int e) {              // 位序 i 从 1 起
        if (i < 1 || i > (int)a.size() + 1) return false;
        a.insert(a.begin() + i - 1, e);          // 内部整体后移 O(n)
        return true;
    }
    bool ListDelete(int i, int &e) {
        if (i < 1 || i > (int)a.size()) return false;
        e = a[i - 1]; a.erase(a.begin() + i - 1); // 内部整体前移 O(n)
        return true;
    }
};
// 实测（demo34）：建 [10,20,30,40,50] 后在 2 插 99 -> [10,99,20,30,40,50]；
// 删位序 4 带出 30 -> [10,99,20,40,50]；越界插入 ListInsert(99,1) 返回 false —— 与 C 版逐项一致。
```

